CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,UNIQUE(org_id,id));
CREATE TABLE memberships(org_id uuid NOT NULL,project_id uuid NOT NULL,subject text NOT NULL,permissions text[] NOT NULL DEFAULT ARRAY['read'],repo_ids uuid[],PRIMARY KEY(project_id,subject),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id));
CREATE TABLE repositories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),remote_url text NOT NULL,default_branch text NOT NULL DEFAULT 'main',UNIQUE(project_id,id),UNIQUE(project_id,remote_url));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),provider text NOT NULL CHECK(provider IN ('claude','codex')),external_session_id text NOT NULL,machine_id text NOT NULL,status text NOT NULL DEFAULT 'active',started_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),UNIQUE(project_id,provider,machine_id,external_session_id));
CREATE TABLE session_repositories(project_id uuid NOT NULL,session_id uuid NOT NULL,repo_id uuid NOT NULL,branch text NOT NULL,head_sha text,PRIMARY KEY(session_id,repo_id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id),FOREIGN KEY(project_id,repo_id) REFERENCES repositories(project_id,id));
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),title text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE context_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),repo_id uuid,session_id uuid,event_type text NOT NULL,idempotency_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,idempotency_key),FOREIGN KEY(project_id,repo_id) REFERENCES repositories(project_id,id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE TABLE context_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),repo_id uuid,session_id uuid,task_id uuid,kind text NOT NULL CHECK(kind IN('fact','decision','finding','proposal','convention','contract')),content text NOT NULL,status text NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','verified_on_branch','verified_on_main','stale','superseded','conflicted')),branch text,commit_sha text,evidence jsonb NOT NULL DEFAULT '[]',version integer NOT NULL DEFAULT 1,superseded_by uuid,valid_from timestamptz NOT NULL DEFAULT now(),valid_to timestamptz,embedding vector(1536),search_document tsvector GENERATED ALWAYS AS (to_tsvector('simple',content)) STORED,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),CHECK(repo_id IS NULL OR branch IS NOT NULL),FOREIGN KEY(project_id,repo_id) REFERENCES repositories(project_id,id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id),FOREIGN KEY(project_id,superseded_by) REFERENCES context_records(project_id,id));
CREATE TABLE context_relations(project_id uuid NOT NULL,from_id uuid NOT NULL,to_id uuid NOT NULL,relation text NOT NULL CHECK(relation IN('depends_on','contradicts','supersedes','related')),PRIMARY KEY(from_id,to_id,relation),FOREIGN KEY(project_id,from_id) REFERENCES context_records(project_id,id),FOREIGN KEY(project_id,to_id) REFERENCES context_records(project_id,id));
CREATE TABLE handoffs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,task_id uuid NOT NULL,session_id uuid NOT NULL,summary text NOT NULL,pending_work jsonb NOT NULL DEFAULT '[]',blockers jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE TABLE outbox_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),repo_id uuid,event_id uuid NOT NULL REFERENCES context_events(id),event_type text NOT NULL,payload jsonb NOT NULL,published_at timestamptz,processed_at timestamptz,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,repo_id) REFERENCES repositories(project_id,id));
CREATE TABLE task_leases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,task_id uuid NOT NULL,session_id uuid NOT NULL,repo_id uuid NOT NULL,owner text NOT NULL,branch text NOT NULL,resources text[] NOT NULL,expires_at timestamptz NOT NULL,UNIQUE(task_id,session_id),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id),FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id),FOREIGN KEY(project_id,repo_id) REFERENCES repositories(project_id,id));
CREATE TABLE delta_cursors(project_id uuid NOT NULL REFERENCES projects(id),subject text NOT NULL,scope_hash text NOT NULL,cursor bigint NOT NULL DEFAULT 0,PRIMARY KEY(project_id,subject,scope_hash));
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),subject text NOT NULL,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX context_scope_idx ON context_records(project_id,repo_id,status,branch);
CREATE INDEX context_search_idx ON context_records USING gin(search_document);
CREATE INDEX context_embedding_idx ON context_records USING hnsw(embedding vector_cosine_ops);
CREATE INDEX outbox_pending_idx ON outbox_events(id) WHERE published_at IS NULL;
CREATE INDEX delta_scope_idx ON outbox_events(project_id,id);
CREATE INDEX lease_expiry_idx ON task_leases(project_id,repo_id,expires_at);
-- Memberships are provisioned only by the migration/admin role, never by the API.
CREATE ROLE sce_app NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE ON SCHEMA public TO sce_app;
GRANT SELECT ON organizations,projects,memberships,repositories TO sce_app;
GRANT SELECT,INSERT,UPDATE ON sessions,session_repositories,tasks,context_events,context_records,context_relations,handoffs,outbox_events,task_leases,delta_cursors,audit_logs TO sce_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO sce_app;
CREATE FUNCTION sce_allowed(pid uuid,rid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT EXISTS(SELECT 1 FROM memberships m WHERE m.project_id=pid AND m.org_id::text=current_setting('sce.org_id',true) AND m.subject=current_setting('sce.subject',true) AND (rid IS NULL OR m.repo_ids IS NULL OR rid=ANY(m.repo_ids)))
$$;
ALTER TABLE repositories ENABLE ROW LEVEL SECURITY;
ALTER TABLE repositories FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON repositories USING (sce_allowed(project_id,id)) WITH CHECK (sce_allowed(project_id,id));
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON sessions USING (sce_allowed(project_id)) WITH CHECK (sce_allowed(project_id));
ALTER TABLE session_repositories ENABLE ROW LEVEL SECURITY;
ALTER TABLE session_repositories FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON session_repositories USING (sce_allowed(project_id,repo_id)) WITH CHECK (sce_allowed(project_id,repo_id));
ALTER TABLE tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE tasks FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON tasks USING (sce_allowed(project_id)) WITH CHECK (sce_allowed(project_id));
ALTER TABLE context_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE context_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON context_events USING (sce_allowed(project_id,repo_id)) WITH CHECK (sce_allowed(project_id,repo_id));
ALTER TABLE context_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE context_records FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON context_records USING (sce_allowed(project_id,repo_id)) WITH CHECK (sce_allowed(project_id,repo_id));
ALTER TABLE context_relations ENABLE ROW LEVEL SECURITY;
ALTER TABLE context_relations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON context_relations USING (sce_allowed(project_id)) WITH CHECK (sce_allowed(project_id));
ALTER TABLE handoffs ENABLE ROW LEVEL SECURITY;
ALTER TABLE handoffs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON handoffs USING (sce_allowed(project_id)) WITH CHECK (sce_allowed(project_id));
ALTER TABLE outbox_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE outbox_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON outbox_events USING (sce_allowed(project_id,repo_id)) WITH CHECK (sce_allowed(project_id,repo_id));
ALTER TABLE task_leases ENABLE ROW LEVEL SECURITY;
ALTER TABLE task_leases FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON task_leases USING (sce_allowed(project_id,repo_id)) WITH CHECK (sce_allowed(project_id,repo_id));
ALTER TABLE delta_cursors ENABLE ROW LEVEL SECURITY;
ALTER TABLE delta_cursors FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON delta_cursors USING (sce_allowed(project_id)) WITH CHECK (sce_allowed(project_id));
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_logs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON audit_logs USING (sce_allowed(project_id)) WITH CHECK (sce_allowed(project_id));
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_identity ON organizations USING(id::text=current_setting('sce.org_id',true));
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_identity ON projects USING(org_id::text=current_setting('sce.org_id',true) AND sce_allowed(id));
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY member_identity ON memberships USING(org_id::text=current_setting('sce.org_id',true) AND subject=current_setting('sce.subject',true));
